-- Verificação posterior somente leitura da Migration 013.
SELECT VERSION() AS mysql_version;
SELECT DATABASE() AS selected_database;
SELECT COUNT(*) AS schema_migrations_table_present FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name = 'schema_migrations';
SELECT COUNT(*) AS migration_013_count FROM __DOCMOTOR_DATABASE__.schema_migrations WHERE name = '013_suspension_documentation_fields.sql';
SELECT COUNT(*) AS required_documentary_fields_count FROM __DOCMOTOR_DATABASE__.service_form_fields f JOIN __DOCMOTOR_DATABASE__.service_versions v ON v.id = f.service_version_id JOIN __DOCMOTOR_DATABASE__.services s ON s.id = v.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 AND f.field_key IN ('suspension.parts_invoice', 'suspension.installation_invoice') AND f.field_type = 'SINGLE_SELECT' AND f.is_required = 1 AND f.default_value IS NULL;
SELECT f.field_key, f.label, f.is_required, f.default_value, COUNT(o.id) AS option_count FROM __DOCMOTOR_DATABASE__.service_form_fields f JOIN __DOCMOTOR_DATABASE__.service_versions v ON v.id = f.service_version_id JOIN __DOCMOTOR_DATABASE__.services s ON s.id = v.service_id LEFT JOIN __DOCMOTOR_DATABASE__.service_field_options o ON o.field_id = f.id WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 AND f.field_key IN ('suspension.parts_invoice', 'suspension.installation_invoice') GROUP BY f.id, f.field_key, f.label, f.is_required, f.default_value ORDER BY f.display_order;
SELECT f.field_key, o.option_value, o.option_label FROM __DOCMOTOR_DATABASE__.service_field_options o JOIN __DOCMOTOR_DATABASE__.service_form_fields f ON f.id = o.field_id JOIN __DOCMOTOR_DATABASE__.service_versions v ON v.id = f.service_version_id JOIN __DOCMOTOR_DATABASE__.services s ON s.id = v.service_id WHERE s.code = 'LOWERED_SUSPENSION' AND v.version_number = 1 AND f.field_key IN ('suspension.parts_invoice', 'suspension.installation_invoice') ORDER BY f.display_order, o.display_order;
